#!/usr/bin/env python3
import sys, os, re, glob, subprocess, shlex, json, base64, binascii, random, time, math, difflib, traceback

VERSION_STR = "Hush 0.1.4"
HELP_TEXT = "Hush 0.1.4\ngahag <gabriel.s.b@live.com>\nHush is a unix shell scripting language based on the Lua programming language\n\nUSAGE:\n    executable [FLAGS] [arguments]...\n\nFLAGS:\n        --ast        Print the AST\n        --check      Perform only static analysis instead of executing.\n    -h, --help       Prints help information\n        --lex        Print the lexemes\n        --program    Print the PROGAM\n    -V, --version    Prints version information\n\nARGS:\n    <arguments>...    Script and/or arguments\n"

def parse_cli(argv):
    flags_set = {}
    positionals = []
    parsed_flags = []
    end_of_flags = False
    first_help_or_version = None
    j = 0
    while j < len(argv):
        arg = argv[j]
        if end_of_flags:
            positionals.append(arg)
            j+=1
            continue
        if arg == "--":
            end_of_flags=True
            j+=1
            continue
        if arg.startswith("--"):
            if "=" in arg:
                name_part, val = arg.split("=",1)
            else:
                name_part = arg
                val = None
            flag_name = name_part[2:]
            if flag_name in ("ast","check","lex","program","help","version"):
                canon = flag_name
                if canon in ("help","version"):
                    if first_help_or_version is None:
                        first_help_or_version = canon
                else:
                    if canon in flags_set:
                        uniq = sorted(set(parsed_flags))
                        usage = " ".join("--"+x for x in uniq)
                        if usage:
                            usage_str = f"    executable {usage}\n"
                        else:
                            usage_str = f"    executable [FLAGS] [arguments]...\n"
                        msg = f"error: The argument '--{canon}' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n{usage_str}\nFor more information try --help\n"
                        return None, None, (msg, 1)
                    flags_set[canon]=True
                    parsed_flags.append(canon)
                j+=1
                continue
            else:
                known = ["ast","check","lex","program","help","version"]
                best=None
                best_ratio=0
                for k in known:
                    r=difflib.SequenceMatcher(None, flag_name, k).ratio()
                    if r>best_ratio:
                        best_ratio=r
                        best=k
                suggest=None
                if best_ratio>0.6:
                    suggest=best
                if suggest:
                    uniq = sorted(set(parsed_flags + [suggest]))
                    usage = " ".join("--"+x for x in uniq)
                    usage_str = f"    executable {usage}\n"
                    msg = f"error: Found argument '--{flag_name}' which wasn't expected, or isn't valid in this context\n\tDid you mean \x1b[32m--\x1b[0m\x1b[32m{suggest}\x1b[0m?\n\nUSAGE:\n{usage_str}\nFor more information try --help\n"
                else:
                    if parsed_flags:
                        uniq=sorted(set(parsed_flags))
                        usage=" ".join("--"+x for x in uniq)
                        usage_str=f"    executable {usage}\n"
                    else:
                        usage_str=f"    executable [FLAGS] [arguments]...\n"
                    msg = f"error: Found argument '--{flag_name}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n{usage_str}\nFor more information try --help\n"
                return None, None, (msg, 1)
        elif arg.startswith("-") and len(arg)>1:
            raw = arg[1:]
            if "=" in raw:
                left, right = raw.split("=",1)
                flags_part = left
            else:
                flags_part = raw
            unknown_found=None
            for ch in flags_part:
                if ch=="h":
                    if first_help_or_version is None:
                        first_help_or_version="help"
                elif ch=="V":
                    if first_help_or_version is None:
                        first_help_or_version="version"
                else:
                    unknown_found=ch
                    break
            if unknown_found is not None:
                if parsed_flags:
                    uniq=sorted(set(parsed_flags))
                    usage=" ".join("--"+x for x in uniq)
                    usage_str=f"    executable {usage}\n"
                else:
                    usage_str=f"    executable [FLAGS] [arguments]...\n"
                msg=f"error: Found argument '-{unknown_found}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n{usage_str}\nFor more information try --help\n"
                return None, None, (msg,1)
            j+=1
            continue
        else:
            positionals.append(arg)
            j+=1
            end_of_flags=True
            continue
    if first_help_or_version=="help":
        return {"help":True}, positionals, None
    if first_help_or_version=="version":
        return {"version":True}, positionals, None
    result={"lex": "lex" in flags_set, "ast": "ast" in flags_set, "program": "program" in flags_set, "check": "check" in flags_set}
    return result, positionals, None
PYEOF
echo "chunk1 done"; wc -l src/hush.py
