            return "@[]"
        parts=[]
        for k,v in self.d.items():
            # Keys are strings (identifiers), values display with collection quoting?
            # Example: @[ "a": 1 ] with quotes around key, even though key was identifier a (without quotes). So keys always quoted in display.
            # Values: if string, quoted? For @[a:"hi"], display would be '@[ "a": "hi" ]'? Probably.
