        v = env.get(node.name)
        if v is None:
            raise HushPanic(filename, node.line, node.col, f"undeclared variable '{node.name}'")
        return v
    if isinstance(node, SelfVar):
        v = env.get("self")
        if v is None:
            # Need line/col for self? SelfVar currently has no line/col (we didn't store). Use 1,0 for now, but should be actual.
            raise HushPanic(filename, 1, 0, "undeclared variable 'self'")
        return v
