            if not isinstance(left, HushString):
                l,c = pos_of(node.left)
                disp = _display_for_panic(left)
                raise HushPanic(filename, l, c, f"value ({disp}) has unexpected type, expected string")
            else:
                l,c = pos_of(node.right)
                disp = _display_for_panic(right)
                raise HushPanic(filename, l, c, f"value ({disp}) has unexpected type, expected string")
        if op in ("and","or"):
            if op=="and":
                return right if _is_truthy(left) else left
            else:
