        raise HushPanic(filename, 1, 0, "unknown binop")
    if isinstance(node, UnOp):
        v = eval_full(node.expr, env, filename)
        l,c = (getattr(node.expr,'line',1), getattr(node.expr,'col',0))
        # Also need op position? For unary, panic at expr position? Probably.
        if node.op=="not":
