            raise HushPanic(filename, l, c, f"value ({disp}) has unexpected type, expected int or float")
        raise HushPanic(filename, l, c, "unknown unary")
    # TODO: Call, Index, Field, Array, Dict, Func, IfExpr, CmdBlock
    raise HushPanic(filename, 1, 0, f"eval not implemented for {type(node).__name__}")

