def do_exec_stmt(stmt, env, filename):
    if isinstance(stmt, LetStmt):
        v = eval_full(stmt.expr, env, filename) if stmt.expr else HushNil()
        env.declare(stmt.name, v)
        return v
    if isinstance(stmt, AssignStmt):
        v = eval_full(stmt.expr, env, filename)
        do_assign(stmt.target, v, env, filename)
        return v
    if isinstance(stmt, ExprStmt):
        return eval_full(stmt.expr, env, filename)
    if isinstance(stmt, IfStmt):
        cond = eval_full(stmt.cond, env, filename)
        if _is_truthy(cond):
            child = Env(parent=env)
            for s in stmt.then_block:
                do_exec_stmt(s, child, filename)
        else:
            if stmt.else_block is not None:
                child = Env(parent=env)
                for s in stmt.else_block:
                    do_exec_stmt(s, child, filename)
        return HushNil()
    if isinstance(stmt, ForStmt):
        do_for_stmt(stmt, env, filename)
        return HushNil()
    if isinstance(stmt, WhileStmt):
        do_while_stmt(stmt, env, filename)
        return HushNil()
    if isinstance(stmt, ReturnStmt):
        if stmt.expr is None:
            raise HushReturn(HushNil())
        else:
            raise HushReturn(eval_full(stmt.expr, env, filename))
    if isinstance(stmt, BreakStmt):
        raise HushBreak()
    if isinstance(stmt, IllFormed):
