def eval_full(node, env, filename):
    if isinstance(node, LitNil):
        return HushNil()
    if isinstance(node, LitBool):
        return HushBool(node.v)
    if isinstance(node, LitInt):
        return HushInt(node.v)
    if isinstance(node, LitFloat):
        return HushFloat(node.v)
    if isinstance(node, LitString):
        return HushString(node.s)
    if isinstance(node, LitChar):
        return HushChar(node.c)
    if isinstance(node, Var):
        v = env.get(node.name)
        if v is None:
            raise HushPanic(filename, node.line, node.col, f"undeclared variable '{node.name}'")
        return v
    if isinstance(node, SelfVar):
        v = env.get("self")
        if v is None:
            raise HushPanic(filename, 1, 0, "undeclared variable 'self'")
        return v
    if isinstance(node, BinOp):
        left = eval_full(node.left, env, filename)
        right = eval_full(node.right, env, filename)
        op = node.op
        def pos_of(n):
            return (getattr(n, 'line', 1), getattr(n, 'col', 0))
        if op in ("+", "-", "*", "/", "%"):
            if isinstance(left, HushInt) and isinstance(right, HushInt):
                if op == "+": return HushInt(left.v + right.v)
                if op == "-": return HushInt(left.v - right.v)
                if op == "*": return HushInt(left.v * right.v)
                if op == "/":
                    if right.v == 0:
                        l,c = pos_of(node.right)
                        raise HushPanic(filename, l, c, "division by zero")
                    import math
                    return HushInt(math.trunc(left.v / right.v))
                if op == "%":
                    if right.v == 0:
                        l,c = pos_of(node.right)
                        raise HushPanic(filename, l, c, "division by zero")
                    import math
                    q = math.trunc(left.v / right.v)
                    return HushInt(left.v - q * right.v)
            elif isinstance(left, HushFloat) and isinstance(right, HushFloat):
                if op == "+": return HushFloat(left.v + right.v)
                if op == "-": return HushFloat(left.v - right.v)
                if op == "*": return HushFloat(left.v * right.v)
                if op == "/": return HushFloat(left.v / right.v if right.v != 0 else float('inf'))
                if op == "%": return HushFloat(left.v % right.v if right.v != 0 else float('nan'))
            else:
                if not isinstance(left, (HushInt, HushFloat)):
                    l,c = pos_of(node.left)
                    disp = _display_for_panic(left)
                    raise HushPanic(filename, l, c, f"value ({disp}) has unexpected type, expected int or float")
                else:
                    exp = "int" if isinstance(left, HushInt) else "float"
                    l,c = pos_of(node.right)
                    disp = _display_for_panic(right)
                    raise HushPanic(filename, l, c, f"value ({disp}) has unexpected type, expected {exp}")
        if op in ("==", "!="):
            def deep_eq(a,b):
                if (a is None or isinstance(a, HushNil)) and (b is None or isinstance(b, HushNil)):
                    return True
                if type(a) != type(b):
                    return False
                if isinstance(a, HushNil):
                    return True
                if isinstance(a, HushBool):
                    return a.v == b.v
                if isinstance(a, HushInt):
                    return a.v == b.v
                if isinstance(a, HushFloat):
                    return a.v == b.v
                if isinstance(a, HushChar):
                    return a.c == b.c
                if isinstance(a, HushString):
                    return a.s == b.s
                if isinstance(a, HushArray):
                    if len(a.elems) != len(b.elems):
                        return False
                    return all(deep_eq(x,y) for x,y in zip(a.elems, b.elems))
                if isinstance(a, HushDict):
                    if set(a.d.keys()) != set(b.d.keys()):
                        return False
                    return all(deep_eq(a.d[k], b.d[k]) for k in a.d)
                if isinstance(a, HushFunc):
                    return a is b
                if isinstance(a, HushError):
                    return a is b
                return False
            eq = deep_eq(left, right)
            return HushBool(eq if op=="==" else not eq)
        if op in ("<", "<=", ">", ">="):
            def cmp_vals(a,b,op):
                if op=="<": return a<b
                if op=="<=": return a<=b
                if op==">": return a>b
                if op==">=": return a>=b
            if isinstance(left, HushInt) and isinstance(right, HushInt):
                return HushBool(cmp_vals(left.v, right.v, op))
            if isinstance(left, HushFloat) and isinstance(right, HushFloat):
                return HushBool(cmp_vals(left.v, right.v, op))
            if isinstance(left, HushString) and isinstance(right, HushString):
                return HushBool(cmp_vals(left.s, right.s, op))
            if isinstance(left, HushChar) and isinstance(right, HushChar):
                return HushBool(cmp_vals(left.c, right.c, op))
            if hush_type_name(left) not in ("int","float","string","char"):
                l,c = pos_of(node.left)
                disp = _display_for_panic(left)
                raise HushPanic(filename, l, c, f"value ({disp}) has unexpected type, expected int")
            else:
                exp = hush_type_name(left)
                l,c = pos_of(node.right)
                disp = _display_for_panic(right)
                raise HushPanic(filename, l, c, f"value ({disp}) has unexpected type, expected {exp}")
        if op == "++":
            if isinstance(left, HushString) and isinstance(right, HushString):
                return HushString(left.s + right.s)
            if not isinstance(left, HushString):
                l,c = pos_of(node.left)
                disp = _display_for_panic(left)
                raise HushPanic(filename, l, c, f"value ({disp}) has unexpected type, expected string")
            else:
                l,c = pos_of(node.right)
                disp = _display_for_panic(right)
                raise HushPanic(filename, l, c, f"value ({disp}) has unexpected type, expected string")
        if op in ("and","or"):
            if op=="and":
                return right if _is_truthy(left) else left
            else:
                return left if _is_truthy(left) else right
        raise HushPanic(filename, 1, 0, "unknown binop")
    if isinstance(node, UnOp):
        v = eval_full(node.expr, env, filename)
        l,c = (getattr(node.expr,'line',1), getattr(node.expr,'col',0))
        if node.op=="not":
            return HushBool(not _is_truthy(v))
        if node.op=="-":
            if isinstance(v, HushInt):
                return HushInt(-v.v)
            if isinstance(v, HushFloat):
                return HushFloat(-v.v)
            disp = _display_for_panic(v)
            raise HushPanic(filename, l, c, f"value ({disp}) has unexpected type, expected int or float")
        raise HushPanic(filename, l, c, "unknown unary")
    if isinstance(node, ArrayLit):
        return HushArray([eval_full(e, env, filename) for e in node.elems])
    if isinstance(node, DictLit):
        d = {}
        for k, v in node.pairs:
            vv = eval_full(v, env, filename)
            if isinstance(k, str):
                d[k] = vv
            else:
                d["ill"] = vv
        return HushDict(d)
    if isinstance(node, FuncExpr):
        return HushFunc(node.params, node.body, env, filename=filename, line=1, col=0)
    if isinstance(node, IfExpr):
        cond = eval_full(node.cond, env, filename)
        if _is_truthy(cond):
            child = Env(parent=env)
            res = HushNil()
            for st in node.then_block:
                if isinstance(st, ExprStmt):
                    res = eval_full(st.expr, child, filename)
                elif isinstance(st, LetStmt):
                    v = eval_full(st.expr, child, filename) if st.expr else HushNil()
                    child.declare(st.name, v)
                    res = v
                else:
                    res = HushNil()
            return res
        else:
            if node.else_block is None:
                return HushNil()
            child = Env(parent=env)
            res = HushNil()
            for st in node.else_block:
                if isinstance(st, ExprStmt):
                    res = eval_full(st.expr, child, filename)
                elif isinstance(st, LetStmt):
                    v = eval_full(st.expr, child, filename) if st.expr else HushNil()
                    child.declare(st.name, v)
                    res = v
                else:
                    res = HushNil()
            return res
    raise HushPanic(filename, 1, 0, "eval todo")
