def eval_full(node, env, filename):
    if isinstance(node, LitNil):
        return HushNil()
    if isinstance(node, LitBool):
        return HushBool(node.v)
    if isinstance(node, LitInt):
        return HushInt(node.v)
    if isinstance(node, LitFloat):
        return HushFloat(node.v)
    if isinstance(node, LitString):
        return HushString(node.s)
    if isinstance(node, LitChar):
        return HushChar(node.c)
    if isinstance(node, Var):
        v = env.get(node.name)
        if v is None:
            raise HushPanic(filename, node.line, node.col, f"undeclared variable '{node.name}'")
        return v
    if isinstance(node, SelfVar):
        v = env.get("self")
        if v is None:
            raise HushPanic(filename, 1, 0, "undeclared variable 'self'")
        return v
    if isinstance(node, BinOp):
        left = eval_full(node.left, env, filename)
        right = eval_full(node.right, env, filename)
        op = node.op
        def pos_of(n):
            return (getattr(n, 'line', 1), getattr(n, 'col', 0))
        if op in ("+", "-", "*", "/", "%"):
            if isinstance(left, HushInt) and isinstance(right, HushInt):
                if op == "+": return HushInt(left.v + right.v)
                if op == "-": return HushInt(left.v - right.v)
                if op == "*": return HushInt(left.v * right.v)
                if op == "/":
                    if right.v == 0:
                        l,c = pos_of(node.right)
                        raise HushPanic(filename, l, c, "division by zero")
                    import math
                    return HushInt(math.trunc(left.v / right.v))
                if op == "%":
                    if right.v == 0:
                        l,c = pos_of(node.right)
                        raise HushPanic(filename, l, c, "division by zero")
                    import math
                    q = math.trunc(left.v / right.v)
                    return HushInt(left.v - q * right.v)
            elif isinstance(left, HushFloat) and isinstance(right, HushFloat):
                if op == "+": return HushFloat(left.v + right.v)
                if op == "-": return HushFloat(left.v - right.v)
                if op == "*": return HushFloat(left.v * right.v)
                if op == "/": return HushFloat(left.v / right.v if right.v != 0 else float('inf'))
                if op == "%": return HushFloat(left.v % right.v if right.v != 0 else float('nan'))
            else:
                if not isinstance(left, (HushInt, HushFloat)):
                    l,c = pos_of(node.left)
                    disp = _display_for_panic(left)
                    raise HushPanic(filename, l, c, f"value ({disp}) has unexpected type, expected int or float")
                else:
                    exp = "int" if isinstance(left, HushInt) else "float"
                    l,c = pos_of(node.right)
                    disp = _display_for_panic(right)
                    raise HushPanic(filename, l, c, f"value ({disp}) has unexpected type, expected {exp}")
        if op in ("==", "!="):
            def deep_eq(a,b):
                if (a is None or isinstance(a, HushNil)) and (b is None or isinstance(b, HushNil)):
                    return True
                if type(a) != type(b):
                    return False
                if isinstance(a, HushNil):
                    return True
                if isinstance(a, HushBool):
                    return a.v == b.v
                if isinstance(a, HushInt):
                    return a.v == b.v
                if isinstance(a, HushFloat):
                    return a.v == b.v
                if isinstance(a, HushChar):
                    return a.c == b.c
                if isinstance(a, HushString):
                    return a.s == b.s
                if isinstance(a, HushArray):
                    if len(a.elems) != len(b.elems):
                        return False
                    return all(deep_eq(x,y) for x,y in zip(a.elems, b.elems))
                if isinstance(a, HushDict):
                    if set(a.d.keys()) != set(b.d.keys()):
