def do_exec_stmt_simple(stmt, env, filename):
    if isinstance(stmt, LetStmt):
        v = eval_full(stmt.expr, env, filename) if stmt.expr else HushNil()
        env.declare(stmt.name, v)
        return v
    if isinstance(stmt, AssignStmt):
        v = eval_full(stmt.expr, env, filename)
        # Handle assign target (Var, Field, Index)
        tgt = stmt.target
        if isinstance(tgt, Var):
            e = env
            while e:
                if tgt.name in e.vars:
                    e.vars[tgt.name] = v
                    break
                e = e.parent
            else:
                env.declare(tgt.name, v)
        elif isinstance(tgt, Field):
            obj = eval_full(tgt.obj, env, filename)
            if isinstance(obj, HushDict):
                obj.d[tgt.field] = v
            else:
                disp = _display_for_panic(obj)
                l,c = (getattr(tgt.obj,'line',1), getattr(tgt.obj,'col',0))
                raise HushPanic(filename, l, c, f"value ({disp}) has unexpected type, expected dict")
        elif isinstance(tgt, Index):
            obj = eval_full(tgt.obj, env, filename)
            idx = eval_full(tgt.idx, env, filename)
            if isinstance(obj, HushArray) and isinstance(idx, HushInt):
                if idx.v < 0 or idx.v >= len(obj.elems):
                    l,c = (getattr(tgt.idx,'line',1), getattr(tgt.idx,'col',0))
                    raise HushPanic(filename, l, c, f"index ({idx.v}) out of bounds")
                obj.elems[idx.v] = v
            elif isinstance(obj, HushDict) and isinstance(idx, (HushString, HushChar)):
                key = idx.s if isinstance(idx, HushString) else idx.c
                obj.d[key] = v
            else:
                l,c = (getattr(tgt.obj,'line',1), getattr(tgt.obj,'col',0))
                disp = _display_for_panic(obj)
                raise HushPanic(filename, l, c, f"value ({disp}) has unexpected type, expected array or dict")
        return v
    if isinstance(stmt, ExprStmt):
        return eval_full(stmt.expr, env, filename)
    # For other stmts (If, For, While, Return, Break) handle minimally for now (return nil)
    if isinstance(stmt, IfStmt):
        cond = eval_full(stmt.cond, env, filename)
        if _is_truthy(cond):
            child = Env(parent=env)
            for s in stmt.then_block:
                do_exec_stmt_simple(s, child, filename)
        else:
            if stmt.else_block is not None:
                child = Env(parent=env)
                for s in stmt.else_block:
                    do_exec_stmt_simple(s, child, filename)
        return HushNil()
    return HushNil()
