            raise HushPanic(filename, idx_line, idx_col, f"value ({disp}) has unexpected type, expected int")
        if idx.v < 0 or idx.v >= len(obj.s):
            raise HushPanic(filename, idx_line, idx_col, f"index ({idx.v}) out of bounds")
        return HushChar(obj.s[idx.v])
