        if not isinstance(idx, HushInt):
            disp = _display_for_panic(idx)
            raise HushPanic(filename, idx_line, idx_col, f"value ({disp}) has unexpected type, expected int")
        if idx.v < 0 or idx.v >= len(obj.elems):
            raise HushPanic(filename, idx_line, idx_col, f"index ({idx.v}) out of bounds")
        return obj.elems[idx.v]
    if isinstance(obj, HushDict):
        if isinstance(idx, HushString):
