def do_exec_stmt(node, env, filename):
    if isinstance(node, LetStmt):
        v = eval_full(node.expr, env, filename) if node.expr else HushNil()
        env.declare(node.name, v)
        return v
    if isinstance(node, ExprStmt):
        return eval_full(node.expr, env, filename)
    return HushNil()

def execute_program(stmts, filename, args):
    env = Env()
    std_dict = {}
    def mk(n):
        return HushFunc([], None, None, is_std=True, std_name=n)
    for n in ["print", "println"]:
        std_dict[n] = mk("std."+n)
    env.declare("std", HushDict(std_dict))
    for st in stmts:
        do_exec_stmt(st, env, filename)
    return 0
