{"command": "cat > /tmp/expand_exec.py <<'MYEND'
def expand_word_for_exec(lexeme, env, filename):
    s = lexeme
    res = ""
    i = 0
    n = len(s)
    while i < n:
        if s.startswith("${{", i):
            j = s.find("}}", i)
            if j != -1:
                ident = s[i+3:j]
                v = env.get(ident)
                if v is None:
                    raise HushPanic(filename, 1, 0, "bad var")
                res += hush_to_shell_str(v)
                i = j+2
