def do_cmd_block_basic(node, env, filename):
    kind = node.kind
    if len(node.pipelines) == 1 and len(node.pipelines[0]) == 1:
        simp = node.pipelines[0][0]
        if not simp['redirects'] and not simp['question']:
            args = []
            for w in simp['words']:
                expanded = shell_expand_for_exec2(w, env, filename)
                args.extend(expanded)
            if not args:
                if kind == "{":
                    return HushNil()
                elif kind == "${":
                    return HushDict({"stdout": HushString(""), "stderr": HushString("")})
                else:
                    return HushDict({"join": HushFunc([], None, None, is_std=True, std_name="join")})
            import subprocess as _sp
            cmd_args = args
            try:
                if kind == "{":
                    r = _sp.run(cmd_args)
                    if r.returncode == 0:
                        return HushNil()
                    else:
                        return HushError("command returned non-zero", HushDict({"status": HushInt(r.returncode), "pos": HushString(filename+" (line 1, column 0)")}))
                elif kind == "${":
                    r = _sp.run(cmd_args, capture_output=True, text=True)
                    if r.returncode == 0:
                        return HushDict({"stdout": HushString(r.stdout), "stderr": HushString(r.stderr)})
                    else:
                        return HushError("command returned non-zero", HushDict({"stdout": HushString(r.stdout), "stderr": HushString(r.stderr), "error": HushDict({"status": HushInt(r.returncode), "pos": HushString(filename+" (line 1, column 0)")})}))
                else:
                    r = _sp.run(cmd_args)
                    if r.returncode == 0:
                        return HushDict({"join": HushFunc([], None, None, is_std=True, std_name="join")})
                    else:
                        return HushError("command returned non-zero", HushDict({"status": HushInt(r.returncode), "pos": HushString(filename+" (line 1, column 0)")}))
            except FileNotFoundError:
                msg = "No such file or directory (os error 2)"
                if kind == "{":
                    return HushError(msg, HushDict({"status": HushInt(127), "pos": HushString(filename+" (line 1, column 0)")}))
