def shell_expand_for_exec2(lexeme, env, filename):
    base = expand_word_for_exec(lexeme, env, filename)
    is_quoted = ('"' in lexeme or "'" in lexeme)
    s = base
    if not is_quoted and s.startswith("~/"):
        import os as _os2
        s = _os2.environ.get("HOME", "/root") + s[1:]
    if not is_quoted and ('*' in s or '?' in s or '[' in s):
        import glob as _glob2, fnmatch as _fn2, os as _os3
        if "/" not in s:
            try:
                files = _os3.listdir(".")
            except:
                files = []
            matched = [f for f in files if _fn2.fnmatch(f, s)]
            if matched:
                return sorted(["./"+f for f in matched])
            else:
                return [s]
        else:
            try:
                res = _glob2.glob(s)
            except:
                res = []
            if res:
                return sorted(res)
            else:
                return [s]
    return [s]
