                if kind == "{":
                    return HushNil()
                elif kind == "${":
                    return HushDict({"stdout": HushString(""), "stderr": HushString("")})
                else:
                    jf = HushFunc([], None, None, is_std=True, std_name="join")
                    jf.impl = lambda a,e,f,l,c: HushNil()
                    return HushDict({"join": jf})
            import subprocess as _sp
            cmd_args = args
            try:
                if kind == "{":
                    r = _sp.run(cmd_args)
